x}.metric-icon{display:grid;place-items:center;width:30px;height:30px;background:#edf7ee;color:#40885b;border-radius:9px;font-size:16px}.metric-card>strong{display:block;font:800 27px Manrope,sans-serif;letter-spacing:-1px;margin:12px 0 4px}.metric-card>small{color:#9aa49b;font-size:10px}.mini-bar,.progress-track{height:5px;border-radius:10px;background:#edf1ed;overflow:hidden;margin-top:15px}.mini-bar i,.progress-track i{display:block;height:100%;border-radius:10px;background:#51a76d}.quality-bar i{background:#d6a84b}.health-bar i{background:#60ad78}.xp-bar i{background:#7c9ed7}.content-grid{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(270px,1fr);gap:17px;margin-bottom:17px}.panel{padding:20px;min-width:0}.panel-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:15px;margin-bottom:18px}.panel h3,.panel-heading h3{font:800 15px Manrope,sans-serif;margin:0 0 5px}.panel-heading p,.muted{margin:0;color:#929e94;font-size:11px}.text-button{border:0;background:transparent;color:#43885a;font-weight:700;font-size:11px;padding:5px 0}.plant-flow{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px;align-items:stretch}.flow-node{position:relative;border:1px solid #e4ece4;background:#f8fbf8;border-radius:12px;padding:13px 8px;text-align:center;min-height:105px}.flow-node:after{content:'→';position:absolute;right:-11px;top:39%;color:#a3b6a5;font-size:16px;z-index:1}.flow-node:nth-child(4n):after,.flow-node:last-child:after{display:none}.node-icon{font-size:23px;margin-bottom:8px}.node-name{font-size:10px;font-weight:700}.node-stock{font-size:10px;color:#63816a;margin-top:5px}.node-state{display:inline-block;margin-top:8px;font-size:8px;letter-spacing:.5px;padding:4px 6px;border-radius:5px;background:#e2f4e6;color:#34774a}.flow-node.processing{background:#fffaf0;border-color:#f1e1b6}.flow-node.processing .node-state{background:#fff0c9;color:#9c7423}.flow-node.alarm{background:#fff5f4;border-color:#f2cecb}.flow-node.alarm .no