tus-pill.bad{background:#fce4e2;color:#b3443e}.compact-metrics{margin-top:17px}.compact-metrics .metric-card>strong{font-size:23px}.compact-metrics .metric-card>span{color:#849187;font-size:11px}.quality-summary{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:17px}.quality-score-panel{background:linear-gradient(135deg,#f3faf2,#fff);padding:24px}.quality-score-panel>strong{display:block;font:800 42px Manrope,sans-serif;letter-spacing:-2px;margin:14px 0 5px}.quality-score-panel>strong span{font-size:16px;color:#98a59a;letter-spacing:0}.quality-score-panel p{font-size:11px;color:#7d8b80}.range-label{display:flex;justify-content:space-between;margin:18px 0 7px;font-size:11px;color:#6e7f72}.range-label strong{color:#33764b}input[type=range]{width:100%;accent-color:#4b9c65;margin-bottom:10px}.quality-summary .primary-button{margin-top:10px}.equipment-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-bottom:17px}.equipment-card{padding:17px;background:white;border:1px solid #e4ebe4;border-radius:13px;box-shadow:var(--shadow)}.equipment-card .equipment-head{display:flex;align-items:center;gap:10px;margin-bottom:15px}.equipment-icon{width:38px;height:38px;background:#edf7ee;border-radius:11px;display:grid;place-items:center;font-size:19px}.equipment-card h3{font:800 12px Manrope,sans-serif;margin:0 0 4px}.equipment-card small{color:#8c988e;font-size:10px}.equipment-card .status-pill{margin-left:auto}.equipment-stats{display:flex;justify-content:space-between;border-top:1px solid #edf1ed;padding-top:12px;font-size:10px;color:#8b978d}.equipment-stats strong{color:#3f5946}.fault-console{display:grid;grid-template-columns:1fr;gap:15px}.fault-controls{display:flex;align-items:end;gap:10px;flex-wrap:wrap}.fault-controls label{min-width:220px;flex:1}.equipment-actions{display:flex;gap:9px;flex-wrap:wrap}.missions-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}.mission-card{padding:20px;background:white;border