@media(max-width:1180px){.main-area{padding:0 22px 20px}.sidebar{width:220px}.metrics-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.plant-flow{grid-template-columns:repeat(3,minmax(0,1fr))}.flow-node:nth-child(4n):after{display:block}.flow-node:nth-child(3n):after{display:none}.equipment-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:850px){.sidebar{position:fixed;z-index:15;left:-260px;top:0;bottom:0;width:248px;transition:left .25s;box-shadow:12px 0 30px #0002}.sidebar.open{left:0}.mobile-menu{display:block;background:white;border:1px solid var(--line);border-radius:9px;width:37px;height:37px;color:var(--green-800)}.topbar{height:85px}.main-area{padding:0 18px 20px}.topbar h1{font-size:18px}.topbar .eyebrow{font-size:8px}.top-actions{gap:8px}.clock{display:none}.top-actions .primary-button{padding:10px;font-size:10px}.content-grid,.lower-grid{grid-template-columns:1fr}.plant-map{grid-template-columns:repeat(3,minmax(0,1fr))}.missions-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.app-footer{flex-direction:column}.quality-summary{grid-template-columns:1fr}}
@media(max-width:560px){.main-area{padding:0 12px 16px}.topbar{gap:9px}.topbar h1{font-size:16px}.top-actions{margin-left:auto}.icon-button{width:33px;height:33px}.top-actions .primary-button{font-size:0;width:35px;height:35px;padding:0;position:relative}.top-actions .primary-button:after{content:'■';font-size:12px}.welcome-row,.section-intro{align-items:flex-start;flex-direction:column;gap:10px}.welcome-row h2,.section-intro h2{font-size:20px}.date-chip{align-self:flex-start}.metrics-grid{gap:9px}.metric-card{padding:14px}.metric-card>strong{font-size:23px}.metric-card>small{font-size:9px}.metric-top{font-size:10px}.metric-icon{width:26px;height:26px}.panel{padding:15px}.panel-heading{gap:8px}.plant-flow{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.flow-node{min-height:98px}.flow-node:after{display:none!important}.legend{gap:10px;flex-wrap:wrap}.transfer-form{grid-template-columns:1fr 16px 1fr;gap:8px}.transfer-form label:nth-of-type(3){grid-column:1 / 3}.transfer-form>.primary-button{grid-column:3;grid-row:2;padding:9px 6px;font-size:10px}.transfer-form select,.transfer-form input{padding:10px 7px}.plant-map{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.map-node{padding:15px 12px;min-height:130px}.equipment-grid,.missions-grid{grid-template-columns:1fr}.quality-summary{gap:10px}.compact-metrics .metric-card>strong{font-size:20px}.table-panel{padding:0}.fault-controls{align-items:stretch;flex-direction:column}.fault-controls label{min-width:0}.section-intro .primary-button{align-self:flex-start}.app-footer{font-size:9px}.app-footer span:last-child{line-height:1.5}}
